// Severe bug: Constructor calls an overridable method!
public class Super {
    // Broken: constructor calls overridable method!
    public Super() {
        overrideMe();
    }
    public void overrideMe() {}
}

import java.time.Instant;

public class Sub extends Super {
    // Field initialized at subclass construction time
    private final Instant instant;

    public Sub() {
        instant = Instant.now();
    }

    // Overriding method will be called by Super constructor
    // BEFORE the Sub constructor has initialized 'instant'!
    @Override
    public void overrideMe() {
        System.out.println("Instant: " + instant.toString());
    }
}

wrong_code.call_site:
public class Main {
    public static void main(String[] args) {
        // Super() runs -> calls overrideMe() -> instant is null -> NullPointerException!
        Sub sub = new Sub();
    }
}

right_code.class:
// Robust design 1: Prohibit inheritance by marking the class final
public final class SafeService {
    private final String config;

    public SafeService(String config) {
        this.config = config;
    }

    public void performAction() {
        // Reliable execution with no risk of rogue overrides
    }
}

// Robust design 2: If subclassing is required, constructors do not invoke overridables
public abstract class BaseService {
    public BaseService() {
        // Safe: NO overridable methods called during construction!
    }

    /**
     * @implSpec This implementation invokes {@link #validate()} before execution.
     */
    public void execute() {
        validate();
        run();
    }

    protected abstract void validate();
    protected abstract void run();
}

right_code.call_site:
public class Main {
    public static void main(String[] args) {
        SafeService service = new SafeService("production");
        service.performAction(); // Deterministic and secure
    }
}
